def retain(self, child: PiSessionChild, identity: NativeSessionIdentity) -> bool:
        if not child.proc.alive():
            return False
        try:
            revision = SessionRevision.observe(identity.session_file).require_available()
        except SessionRevisionUnavailable:
            return False
        self.custody = RetainedNative(child, identity, revision)
        return True

def parse(cls, arguments: Sequence[str]) -> NativeArguments:
        options = {
            flag: member
            for member in OptionArgument.members_with(OptionArgument)
            for flag in (member.flag(), member.short)
            if flag is not None
        }
        result = []
        source = iter(arguments)
        for token in source:
            name, separator, value = token.partition("=")
            member = options.get(name)
            result.append(
                member.consume(value if separator else None, source)
                if member is not None
                else ExternalArgument((token,))
            )
        return cls(tuple(result))

def model(self) -> str | None:
        selected = next(
            (entry for entry in reversed(self.entries) if isinstance(entry, ModelArgument)), None
        )
        return selected.qualified(self.value(ProviderArgument)) if selected is not None else None

def retire_owned(self, identity: NativeSessionIdentity, binding: LiveThreadOwnerBinding,
                     arguments: NativeArguments, worktree: Path) -> NativeCustody:
        raise NativePiUnavailable("Native custody cannot retire the original selected child")

def retire_owned(self, identity, binding, arguments, worktree):
        self.child.require_source_owner(identity, binding, arguments, worktree)
        return self

async def closed(self):
        try:
            await asyncio.shield(self.task)
        except Exception as error:
            if self.child.proc.retired:
                raise NativeCleanupFailed(self.successor, error) from error
            raise
        return self.successor

def retire_owned(self, identity, binding, arguments, worktree):
        self.child.require_source_owner(identity, binding, arguments, worktree)
        return self.retire()

def retire(self, successor=None):
        return RetiringNative(
            asyncio.create_task(self.child.close()),
            self.successor if successor is None else successor,
            self.child,
        )

def retire_owned(self, identity, binding, arguments, worktree):
        self.identity.require_same_session(identity)
        return BorrowedNative(self.child, EmptyNative()).retire_owned(identity, binding, arguments, worktree)

def retire(self, successor=None):
        return RetiringNative(
            asyncio.create_task(self.child.close()),
            EmptyNative() if successor is None else successor,
            self.child,
        )

async def finish_result(self) -> AsyncIterator[events.AgentEvent]:
        if not self.native_session.custody.retained:
            self.admission.raise_native_failure(
                NativePiUnavailable(
                    self.output.failure_text or "Native session preparation failed"
                ),
                self.native.attestation,
            )
        if False:
            yield

def prepare_idle_native_source(self, original: RegistryOwner, session_file: str) -> NativeSourcePublication:
        """Retain the idle owner's current turn/task records during selection."""
        current = original.require_idle_source_snapshot(self.snapshot())
        return self._native_source_publication(current, session_file)

def _native_source_publication(self, current: Thread, session_file: str) -> NativeSourcePublication:
        return NativeSourcePublication(
            thread=replace(current, session_file=session_file),
            status=self.statuses[current.name],
            previous=current, previous_status=self.statuses[current.name],
        )

def for_native(cls, snapshot, thread):
        process = thread.require_process()
        owner = snapshot.owner_identity(thread.name)
        snapshot.require_owner_process(owner, process)
        return cls(thread=thread.name, binding=LiveThreadOwnerBinding(owner, process))

def environment(self, root):
        from .runtime import socket_path

        return {
            "AGENT_COMMS_PROJECT_SOCKET": str(socket_path(root, self.binding.process.pid)),
            "AGENT_COMMS_PROJECT_REQUEST": json.dumps(self.to_wire()),
        }

def require_original_local_binding(self, session_id: str, original: RegistryOwner) -> None:
        if self.require(session_id) != original.thread.name or session_id in self.proxies:
            raise RelationViolationError("Native fork requires the original loaded local owner")
